import { describe, it, expect } from "vitest";
import { calculateShipping } from "../src/pricing";

describe("calculateShipping", () => {
  describe("Input validation", () => {
    it("throws TypeError when weight is not finite", () => {
      // SPEC.md Sekcja 1: Walidacja wejścia
      expect(() => calculateShipping(Infinity, "PL", false)).toThrow(
        TypeError,
      );
      expect(() => calculateShipping(NaN, "PL", false)).toThrow(TypeError);
    });

    it("throws RangeError when weight <= 0", () => {
      // SPEC.md Sekcja 1: Walidacja wejścia
      expect(() => calculateShipping(0, "PL", false)).toThrow(RangeError);
      expect(() => calculateShipping(-5, "PL", false)).toThrow(RangeError);
    });

    it("throws RangeError when weight > 100", () => {
      // SPEC.md Sekcja 1: Walidacja wejścia
      expect(() => calculateShipping(100.1, "PL", false)).toThrow(RangeError);
      expect(() => calculateShipping(150, "PL", false)).toThrow(RangeError);
    });
  });

  describe("Base rate by zone", () => {
    it("applies 12 PLN base rate for PL zone", () => {
      // SPEC.md Sekcja 1: Stawka bazowa wedlug strefy
      const result = calculateShipping(5, "PL", false);
      expect(result).toBe(12.0);
    });

    it("applies 29 PLN base rate for EU zone", () => {
      // SPEC.md Sekcja 1: Stawka bazowa wedlug strefy
      const result = calculateShipping(5, "EU", false);
      expect(result).toBe(29.0);
    });

    it("applies 79 PLN base rate for other zones", () => {
      // SPEC.md Sekcja 1: Stawka bazowa wedlug strefy
      const result = calculateShipping(5, "WORLD", false);
      expect(result).toBe(79.0);
    });

    it("applies 79 PLN base rate for unknown zone string", () => {
      // SPEC.md Sekcja 1: Stawka bazowa wedlug strefy
      const result = calculateShipping(5, "UNKNOWN", false);
      expect(result).toBe(79.0);
    });
  });

  describe("Weight surcharge", () => {
    it("adds no surcharge for weight <= 10 kg", () => {
      // SPEC.md Sekcja 1: Doplata wagowa
      const result = calculateShipping(10, "PL", false);
      expect(result).toBe(12.0);
    });

    it("adds 15 PLN surcharge for weight between 10 and 30 kg (exclusive lower, inclusive upper)", () => {
      // SPEC.md Sekcja 1: Doplata wagowa - powyzej 10 kg, do 30 kg wlacznie
      const result = calculateShipping(10.1, "PL", false);
      expect(result).toBe(12.0 + 15.0);
    });

    it("adds 15 PLN surcharge for weight exactly 30 kg", () => {
      // SPEC.md Sekcja 1: Doplata wagowa - do 30 kg wlacznie
      const result = calculateShipping(30, "PL", false);
      expect(result).toBe(12.0 + 15.0);
    });

    it("adds 40 PLN surcharge for weight > 30 kg", () => {
      // SPEC.md Sekcja 1: Doplata wagowa - powyzej 30 kg
      const result = calculateShipping(30.1, "PL", false);
      expect(result).toBe(12.0 + 40.0);
    });

    it("adds 40 PLN surcharge for weight 100 kg", () => {
      // SPEC.md Sekcja 1: Doplata wagowa - powyzej 30 kg
      const result = calculateShipping(100, "PL", false);
      expect(result).toBe(12.0 + 40.0);
    });
  });

  describe("Premium discount", () => {
    it("applies 80% multiplier (20% discount) for premium customer", () => {
      // SPEC.md Sekcja 1: Rabat premium - placi 80% kwoty
      const baseCost = calculateShipping(5, "PL", false); // 12 PLN
      const premiumCost = calculateShipping(5, "PL", true);
      expect(premiumCost).toBe(baseCost * 0.8);
      expect(premiumCost).toBe(9.6);
    });

    it("applies premium discount to shipping with weight surcharge", () => {
      // SPEC.md Sekcja 1: Rabat premium
      const regularCost = calculateShipping(35, "PL", false); // 12 + 40 = 52
      const premiumCost = calculateShipping(35, "PL", true);
      expect(premiumCost).toBe(regularCost * 0.8);
      expect(premiumCost).toBe(41.6);
    });
  });

  describe("Rounding to 2 decimal places", () => {
    it("rounds final cost to 2 decimal places", () => {
      // SPEC.md Sekcja 1: Wynik - zaokraglona do dwoch miejsc po przecinku
      const result = calculateShipping(5, "PL", true); // (12) * 0.8 = 9.6
      expect(result).toBe(9.6);
      expect(Number(result.toFixed(2))).toBe(result);
    });

    it("correctly rounds 41.6 to 2 decimals", () => {
      // SPEC.md Sekcja 1: Wynik
      const result = calculateShipping(35, "PL", true); // (52) * 0.8 = 41.6
      expect(result).toBe(41.6);
    });
  });

  describe("Integration scenarios", () => {
    it("calculates shipping for EU premium customer with heavy weight", () => {
      // SPEC.md Sekcja 1: Pełny scenariusz
      const result = calculateShipping(50, "EU", true); // (29 + 40) * 0.8 = 69 * 0.8 = 55.2
      expect(result).toBe(55.2);
    });

    it("calculates shipping for WORLD zone with light weight", () => {
      // SPEC.md Sekcja 1: Pełny scenariusz
      const result = calculateShipping(3, "WORLD", false); // 79
      expect(result).toBe(79.0);
    });
  });
});

import { describe, it, expect } from "vitest";
import { parseInvoiceId } from "../src/invoiceId";

describe("parseInvoiceId", () => {
  describe("Input validation", () => {
    it("throws TypeError when input is not a string", () => {
      // SPEC.md Sekcja 2: Walidacja - raw nie jest typu string
      expect(() => parseInvoiceId(123 as any)).toThrow(TypeError);
      expect(() => parseInvoiceId(null as any)).toThrow(TypeError);
      expect(() => parseInvoiceId(undefined as any)).toThrow(TypeError);
      expect(() => parseInvoiceId({} as any)).toThrow(TypeError);
    });

    it("throws Error for malformed format", () => {
      // SPEC.md Sekcja 2: Walidacja - wartosc nie pasuje do formatu
      expect(() => parseInvoiceId("FV/2026/9/0042")).toThrow(Error); // month should be 2 digits
      expect(() => parseInvoiceId("FV/26/09/0042")).toThrow(Error); // year should be 4 digits
      expect(() => parseInvoiceId("FV/2026/09/42")).toThrow(Error); // seq should be 4 digits
      expect(() => parseInvoiceId("FV2026090042")).toThrow(Error); // missing slashes
      expect(() => parseInvoiceId("FX/2026/09/0042")).toThrow(Error); // wrong prefix
    });

    it("throws RangeError when year is out of range 2000-2100", () => {
      // SPEC.md Sekcja 2: Walidacja - rok poza zakresem 2000-2100
      expect(() => parseInvoiceId("FV/1999/09/0042")).toThrow(RangeError);
      expect(() => parseInvoiceId("FV/2101/09/0042")).toThrow(RangeError);
    });

    it("throws RangeError when sequence number is 0000", () => {
      // SPEC.md Sekcja 2: Walidacja - numer kolejny rowny 0000
      expect(() => parseInvoiceId("FV/2026/09/0000")).toThrow(RangeError);
    });
  });

  describe("Format parsing", () => {
    it("parses valid invoice ID", () => {
      // SPEC.md Sekcja 2: Format - przyklad poprawnej wartosci
      const result = parseInvoiceId("FV/2026/09/0042");
      expect(result).toEqual({ year: 2026, month: 9, seq: 42 });
    });

    it("strips leading and trailing whitespace", () => {
      // SPEC.md Sekcja 2: Biale znaki na poczatku i koncu sa ignorowane
      const result = parseInvoiceId("  FV/2026/09/0042  ");
      expect(result).toEqual({ year: 2026, month: 9, seq: 42 });
    });

    it("removes leading zeros from parsed numbers", () => {
      // SPEC.md Sekcja 2: Wynik - liczby calkowite bez wiodacych zer
      const result = parseInvoiceId("FV/2026/09/0042");
      expect(result.year).toBe(2026);
      expect(result.month).toBe(9);
      expect(result.seq).toBe(42);
    });
  });

  describe("Month validation", () => {
    it("accepts months 01-09", () => {
      // SPEC.md Sekcja 2: MM - miesiac, dokladnie dwie cyfry z zakresu 01-12
      for (let m = 1; m <= 9; m++) {
        const month = String(m).padStart(2, "0");
        const result = parseInvoiceId(`FV/2026/${month}/0042`);
        expect(result.month).toBe(m);
      }
    });

    it("accepts months 10-12", () => {
      // SPEC.md Sekcja 2: MM - miesiac, dokladnie dwie cyfry z zakresu 01-12
      for (let m = 10; m <= 12; m++) {
        const result = parseInvoiceId(`FV/2026/${m}/0042`);
        expect(result.month).toBe(m);
      }
    });

    it("rejects month 00", () => {
      // SPEC.md Sekcja 2: Format - MM z zakresu 01-12
      expect(() => parseInvoiceId("FV/2026/00/0042")).toThrow(Error);
    });

    it("rejects month 13", () => {
      // SPEC.md Sekcja 2: Format - MM z zakresu 01-12
      expect(() => parseInvoiceId("FV/2026/13/0042")).toThrow(Error);
    });
  });

  describe("Year boundaries", () => {
    it("accepts year 2000", () => {
      // SPEC.md Sekcja 2: Walidacja - rok w zakresu 2000-2100
      const result = parseInvoiceId("FV/2000/01/0001");
      expect(result.year).toBe(2000);
    });

    it("accepts year 2100", () => {
      // SPEC.md Sekcja 2: Walidacja - rok w zakresu 2000-2100
      const result = parseInvoiceId("FV/2100/12/9999");
      expect(result.year).toBe(2100);
    });

    it("rejects year 1999", () => {
      // SPEC.md Sekcja 2: Walidacja - rok poza zakresem 2000-2100
      expect(() => parseInvoiceId("FV/1999/06/0100")).toThrow(RangeError);
    });

    it("rejects year 2101", () => {
      // SPEC.md Sekcja 2: Walidacja - rok poza zakresem 2000-2100
      expect(() => parseInvoiceId("FV/2101/06/0100")).toThrow(RangeError);
    });
  });

  describe("Sequence number boundaries", () => {
    it("accepts sequence 0001", () => {
      // SPEC.md Sekcja 2: Walidacja - numer kolejny != 0000
      const result = parseInvoiceId("FV/2026/01/0001");
      expect(result.seq).toBe(1);
    });

    it("accepts sequence 9999", () => {
      // SPEC.md Sekcja 2: Format - NNNN dokladnie cztery cyfry
      const result = parseInvoiceId("FV/2026/01/9999");
      expect(result.seq).toBe(9999);
    });

    it("rejects sequence 0000", () => {
      // SPEC.md Sekcja 2: Walidacja - numer kolejny rowny 0000
      expect(() => parseInvoiceId("FV/2026/01/0000")).toThrow(RangeError);
    });
  });

  describe("Return types", () => {
    it("returns numbers for all fields (no string conversion)", () => {
      // SPEC.md Sekcja 2: Wynik - liczby calkowite
      const result = parseInvoiceId("FV/2050/03/1234");
      expect(typeof result.year).toBe("number");
      expect(typeof result.month).toBe("number");
      expect(typeof result.seq).toBe("number");
      expect(Number.isInteger(result.year)).toBe(true);
      expect(Number.isInteger(result.month)).toBe(true);
      expect(Number.isInteger(result.seq)).toBe(true);
    });
  });
});

import { describe, it, expect } from "vitest";
import { awardPoints } from "../src/loyalty";

describe("awardPoints", () => {
  describe("Input validation", () => {
    it("throws TypeError when orderValuePLN is not finite", () => {
      // SPEC.md Sekcja 3: Walidacja - ktorakolwiek kwota nie jest liczba skonczona
      expect(() => awardPoints(Infinity, 0)).toThrow(TypeError);
      expect(() => awardPoints(NaN, 0)).toThrow(TypeError);
    });

    it("throws TypeError when lifetimeSpendPLN is not finite", () => {
      // SPEC.md Sekcja 3: Walidacja - ktorakolwiek kwota nie jest liczba skonczona
      expect(() => awardPoints(100, Infinity)).toThrow(TypeError);
      expect(() => awardPoints(100, NaN)).toThrow(TypeError);
    });

    it("throws RangeError when orderValuePLN is negative", () => {
      // SPEC.md Sekcja 3: Walidacja - ktorakolwiek kwota jest ujemna
      expect(() => awardPoints(-1, 0)).toThrow(RangeError);
    });

    it("throws RangeError when lifetimeSpendPLN is negative", () => {
      // SPEC.md Sekcja 3: Walidacja - ktorakolwiek kwota jest ujemna
      expect(() => awardPoints(0, -1)).toThrow(RangeError);
    });
  });

  describe("Points calculation - 1 point per 10 PLN", () => {
    it("awards 0 points for order < 5 PLN (rounds down with banker's rounding)", () => {
      // SPEC.md Sekcja 3: Przelicznik - 1 punkt za kazde 10 zlotych, zaokraglenie metodą bankierska
      const result = awardPoints(4.99, 0);
      expect(result).toBe(0);
    });

    it("awards 1 point for order exactly 10 PLN", () => {
      // SPEC.md Sekcja 3: Przelicznik - 1 punkt za kazde 10 zlotych
      const result = awardPoints(10, 0);
      expect(result).toBe(1);
    });

    it("awards 1 point for order 15 PLN (1.5 points rounds to 2 with banker's rounding)", () => {
      // SPEC.md Sekcja 3: Przelicznik - zaokraglenie do parzystej przy dokladnej polowie
      // 15 / 10 = 1.5, banker's rounding: 1.5 -> 2 (nearest even)
      const result = awardPoints(15, 0);
      expect(result).toBe(2);
    });

    it("awards 2 points for order 25 PLN (2.5 points rounds to 2 with banker's rounding)", () => {
      // SPEC.md Sekcja 3: Przelicznik - zaokraglenie do parzystej przy dokladnej polowie
      // 25 / 10 = 2.5, banker's rounding: 2.5 -> 2 (nearest even)
      const result = awardPoints(25, 0);
      expect(result).toBe(2);
    });

    it("awards 2 points for order 24 PLN (2.4 points rounds to 2)", () => {
      // SPEC.md Sekcja 3: Przelicznik - zaokraglenie metodą bankierska
      // 24 / 10 = 2.4, rounds to 2
      const result = awardPoints(24, 0);
      expect(result).toBe(2);
    });

    it("awards 3 points for order 26 PLN (2.6 points rounds to 3)", () => {
      // SPEC.md Sekcja 3: Przelicznik - zaokraglenie metodą bankierska
      // 26 / 10 = 2.6, rounds to 3
      const result = awardPoints(26, 0);
      expect(result).toBe(3);
    });

    it("awards 35 points for order 350 PLN (35 points rounds to 35)", () => {
      // SPEC.md Sekcja 3: Przelicznik - 1 punkt za kazde 10 zlotych
      // 350 / 10 = 35
      const result = awardPoints(350, 0);
      expect(result).toBe(35);
    });
  });

  describe("VIP multiplier - 2x points for lifetime spend >= 5000 PLN", () => {
    it("applies 2x multiplier when lifetimeSpend is exactly 5000 PLN", () => {
      // SPEC.md Sekcja 3: Mnoznik VIP - co najmniej 5000 zlotych
      // 100 PLN order -> 10 points * 2 = 20 points
      const result = awardPoints(100, 5000);
      expect(result).toBe(20);
    });

    it("applies 2x multiplier when lifetimeSpend > 5000 PLN", () => {
      // SPEC.md Sekcja 3: Mnoznik VIP - co najmniej 5000 zlotych
      const result = awardPoints(100, 5001);
      expect(result).toBe(20);
    });

    it("does NOT apply 2x multiplier when lifetimeSpend < 5000 PLN", () => {
      // SPEC.md Sekcja 3: Mnoznik VIP - co najmniej 5000 zlotych (not < 5000)
      const result = awardPoints(100, 4999);
      expect(result).toBe(10);
    });

    it("applies 2x multiplier to rounded points", () => {
      // SPEC.md Sekcja 3: Limit - stosujemy po naliczeniu mnoznika VIP
      // 15 PLN -> 1.5 -> rounds to 2 -> 2*2 = 4 (for VIP)
      const result = awardPoints(15, 5000);
      expect(result).toBe(4);
    });
  });

  describe("Points cap - max 5000 points per order (after VIP multiplier)", () => {
    it("caps points at 5000 for non-VIP customer", () => {
      // SPEC.md Sekcja 3: Limit - maksymalnie 5000 punktow, po naliczeniu mnoznika VIP
      // 50000 PLN / 10 = 5000 points
      const result = awardPoints(50000, 0);
      expect(result).toBe(5000);
    });

    it("caps points at 5000 even when order value would exceed after 2x multiplier", () => {
      // SPEC.md Sekcja 3: Limit - maksymalnie 5000 punktow, stosujemy po mnoznika VIP
      // 30000 PLN / 10 = 3000 points * 2 = 6000 points, but capped at 5000
      const result = awardPoints(30000, 5000);
      expect(result).toBe(5000);
    });

    it("allows points below cap for VIP", () => {
      // SPEC.md Sekcja 3: Limit - maksymalnie 5000 punktow
      // 20000 PLN / 10 = 2000 points * 2 = 4000 points (below cap)
      const result = awardPoints(20000, 5000);
      expect(result).toBe(4000);
    });

    it("caps at exactly 5000 when VIP multiplier would result in cap", () => {
      // SPEC.md Sekcja 3: Limit - maksymalnie 5000 punktow
      // 25000 PLN / 10 = 2500 points * 2 = 5000 points
      const result = awardPoints(25000, 5000);
      expect(result).toBe(5000);
    });
  });

  describe("Integration scenarios", () => {
    it("calculates points for regular customer with small order", () => {
      // SPEC.md Sekcja 3: Pełny scenariusz
      const result = awardPoints(99, 2000);
      // 99 / 10 = 9.9 -> banker's rounding: 10 (nearest even)
      expect(result).toBe(10);
    });

    it("calculates points for VIP customer with large order hitting cap", () => {
      // SPEC.md Sekcja 3: Pełny scenariusz
      const result = awardPoints(50000, 5000);
      // 50000 / 10 = 5000 * 2 = 10000, capped at 5000
      expect(result).toBe(5000);
    });

    it("calculates points for customer transitioning to VIP at threshold", () => {
      // SPEC.md Sekcja 3: Mnoznik VIP - co najmniej 5000 zlotych
      // lifetimeSpend = 5000 is the exact threshold - should be VIP
      const nonVIP = awardPoints(100, 4999.99);
      const VIP = awardPoints(100, 5000);
      expect(nonVIP).toBe(10);
      expect(VIP).toBe(20);
    });
  });
});

import { describe, it, expect } from "vitest";
import { Cart } from "../src/cart";

describe("Cart", () => {
  describe("add() - Input validation", () => {
    it("throws RangeError when priceGrosz is not integer", () => {
      // SPEC.md Sekcja 4: add() - priceGrosz nie jest calkowita liczba nieujemna
      const cart = new Cart();
      expect(() => cart.add("SKU1", 1.5, 1)).toThrow(RangeError);
    });

    it("throws RangeError when priceGrosz is negative", () => {
      // SPEC.md Sekcja 4: add() - priceGrosz nie jest calkowita liczba nieujemna
      const cart = new Cart();
      expect(() => cart.add("SKU1", -100, 1)).toThrow(RangeError);
    });

    it("allows priceGrosz = 0 (non-negative includes zero)", () => {
      // SPEC.md Sekcja 4: add() - priceGrosz musi byc nieujemne
      const cart = new Cart();
      expect(() => cart.add("SKU1", 0, 1)).not.toThrow();
    });

    it("throws RangeError when qty is not integer", () => {
      // SPEC.md Sekcja 4: add() - qty nie jest calkowita liczba dodatnia
      const cart = new Cart();
      expect(() => cart.add("SKU1", 100, 1.5)).toThrow(RangeError);
    });

    it("throws RangeError when qty is zero", () => {
      // SPEC.md Sekcja 4: add() - qty nie jest calkowita liczba dodatnia
      const cart = new Cart();
      expect(() => cart.add("SKU1", 100, 0)).toThrow(RangeError);
    });

    it("throws RangeError when qty is negative", () => {
      // SPEC.md Sekcja 4: add() - qty nie jest calkowita liczba dodatnia
      const cart = new Cart();
      expect(() => cart.add("SKU1", 100, -1)).toThrow(RangeError);
    });
  });

  describe("add() - Adding items", () => {
    it("adds a single item to empty cart", () => {
      // SPEC.md Sekcja 4: add()
      const cart = new Cart();
      cart.add("SKU1", 1000, 1); // 1000 grosz
      expect(cart.total()).toBe(1000);
    });

    it("sums quantities when adding same SKU twice", () => {
      // SPEC.md Sekcja 4: add() - Dodanie SKU, ktore jest juz w koszyku, sumuje ilosci
      const cart = new Cart();
      cart.add("SKU1", 100, 2);
      cart.add("SKU1", 100, 3);
      expect(cart.total()).toBe(500); // 100 * 5
    });

    it("adds multiple different SKUs", () => {
      // SPEC.md Sekcja 4: add() - dodawanie roznych SKU
      const cart = new Cart();
      cart.add("SKU1", 100, 2); // 200 grosz
      cart.add("SKU2", 300, 1); // 300 grosz
      expect(cart.total()).toBe(500);
    });
  });

  describe("remove() - Input validation", () => {
    it("throws RangeError when qty is not integer", () => {
      // SPEC.md Sekcja 4: remove() - qty nie jest calkowita liczba dodatnia
      const cart = new Cart();
      cart.add("SKU1", 100, 5);
      expect(() => cart.remove("SKU1", 1.5)).toThrow(RangeError);
    });

    it("throws RangeError when qty is zero", () => {
      // SPEC.md Sekcja 4: remove() - qty nie jest calkowita liczba dodatnia
      const cart = new Cart();
      cart.add("SKU1", 100, 5);
      expect(() => cart.remove("SKU1", 0)).toThrow(RangeError);
    });

    it("throws RangeError when qty is negative", () => {
      // SPEC.md Sekcja 4: remove() - qty nie jest calkowita liczba dodatnia
      const cart = new Cart();
      cart.add("SKU1", 100, 5);
      expect(() => cart.remove("SKU1", -1)).toThrow(RangeError);
    });

    it("throws Error when SKU is not in cart", () => {
      // SPEC.md Sekcja 4: remove() - SKU nie ma w koszyku
      const cart = new Cart();
      cart.add("SKU1", 100, 1);
      expect(() => cart.remove("SKU2", 1)).toThrow(Error);
    });

    it("throws Error when SKU not in cart even if cart is not empty", () => {
      // SPEC.md Sekcja 4: remove() - SKU nie ma w koszyku
      const cart = new Cart();
      cart.add("SKU1", 100, 1);
      expect(() => cart.remove("SKU99", 1)).toThrow(Error);
    });
  });

  describe("remove() - Removing items", () => {
    it("reduces quantity of item in cart", () => {
      // SPEC.md Sekcja 4: remove() - zdejmuje wskazana liczbe sztuk
      const cart = new Cart();
      cart.add("SKU1", 100, 5);
      cart.remove("SKU1", 2);
      expect(cart.total()).toBe(300); // 100 * 3
    });

    it("removes all quantities of an item", () => {
      // SPEC.md Sekcja 4: remove() - zdejmuje wskazana liczbe sztuk
      const cart = new Cart();
      cart.add("SKU1", 100, 3);
      cart.remove("SKU1", 3);
      expect(cart.total()).toBe(0);
    });

    it("allows negative quantity after removal (underflow)", () => {
      // SPEC.md Sekcja 4: remove() - spec nie zabrania ujemnych ilosci
      // ale kod sprawdza to przy total()
      const cart = new Cart();
      cart.add("SKU1", 100, 2);
      cart.remove("SKU1", 5); // removes more than added
      expect(() => cart.total()).toThrow(RangeError); // kod sprawdza underflow
    });
  });

  describe("applyCoupon() - Input validation", () => {
    it("throws Error for unknown coupon code", () => {
      // SPEC.md Sekcja 4: applyCoupon() - nieznany kod
      const cart = new Cart();
      cart.add("SKU1", 100, 1);
      expect(() => cart.applyCoupon("UNKNOWN")).toThrow(Error);
    });

    it("throws Error when applying coupon to empty cart", () => {
      // SPEC.md Sekcja 4: applyCoupon() - koszyk jest pusty
      const cart = new Cart();
      expect(() => cart.applyCoupon("SAVE10")).toThrow(Error);
    });
  });

  describe("applyCoupon() - Applying known coupons", () => {
    it("applies SAVE10 coupon (10% discount)", () => {
      // SPEC.md Sekcja 4: applyCoupon() - kod SAVE10 -> 10% rabat
      const cart = new Cart();
      cart.add("SKU1", 1000, 1); // 1000 grosz
      cart.applyCoupon("SAVE10");
      expect(cart.total()).toBe(900); // 1000 * 0.9
    });

    it("applies HALF coupon (50% discount)", () => {
      // SPEC.md Sekcja 4: applyCoupon() - kod HALF -> 50% rabat
      const cart = new Cart();
      cart.add("SKU1", 1000, 1); // 1000 grosz
      cart.applyCoupon("HALF");
      expect(cart.total()).toBe(500); // 1000 * 0.5
